package api

import "testing"

func TestBulkStatusAppliesAllWhenEveryIdIsValid(t *testing.T) {
	srv := startServer(t)
	defer srv.Close()

	t1 := doRequest(t, srv.URL, "POST", "/api/tickets", map[string]any{"subject": "A"})
	t2 := doRequest(t, srv.URL, "POST", "/api/tickets", map[string]any{"subject": "B"})
	id1 := int(t1.body["id"].(float64))
	id2 := int(t2.body["id"].(float64))

	r := doRequest(t, srv.URL, "POST", "/api/tickets/bulk-status", map[string]any{
		"ticketIds": []int{id1, id2}, "status": "closed",
	})
	if r.status != 200 {
		t.Fatalf("expected 200, got %d", r.status)
	}

	check := doRequest(t, srv.URL, "GET", "/api/tickets/"+jsonNum(t1.body["id"]), nil)
	if check.body["status"] != "closed" {
		t.Fatalf("expected closed, got %v", check.body["status"])
	}
}

func TestBulkStatusRejectsWholeBatchOnOneBadId(t *testing.T) {
	srv := startServer(t)
	defer srv.Close()

	t1 := doRequest(t, srv.URL, "POST", "/api/tickets", map[string]any{"subject": "A"})
	id1 := int(t1.body["id"].(float64))

	r := doRequest(t, srv.URL, "POST", "/api/tickets/bulk-status", map[string]any{
		"ticketIds": []int{id1, 999999}, "status": "closed",
	})
	if r.status != 400 {
		t.Fatalf("expected 400, got %d", r.status)
	}

	check := doRequest(t, srv.URL, "GET", "/api/tickets/"+jsonNum(t1.body["id"]), nil)
	if check.body["status"] != "open" {
		t.Fatalf("ticket before the bad id must be UNCHANGED, got status=%v", check.body["status"])
	}
}

